  if (!subcommand || !allowed[command].includes(subcommand)) return usage(`\u041D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u0430\u044F \u043F\u043E\u0434\u043A\u043E\u043C\u0430\u043D\u0434\u0430 ${command} ${subcommand ?? ""}`.trim(), json);
